 function go(next){if(!['start','intro','explore','collectibles','progress','journal'].includes(next))next='start';page=next;for(const [id,node] of Object.entries({start:home,intro,explore,collectibles,progress:overview,journal}))node.hidden=id!==page;nav.querySelectorAll('button').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(page==='explore')renderExplore();if(page==='collectibles')renderCollectibles();if(page==='progress')renderOverview();window.scrollTo({top:0,behavior:'instant'});}
